-- Kebold's Shiny: Craftsman's Writs (the model, the Writs view of the Merchant's Favor page and its pane; the data
-- is Writs.lua, generated by make_addon_writs.py)
-- What each writ costs to deliver, the reputation it gives, and so what one point of reputation costs: which writ,
-- or the Forged Delivery Receipt, is the cheapest way to the next standing.
--
-- It only COUNTS. It never opens, accepts, delivers or uses anything, never buys or posts: the scan only looks
-- prices up, "Add to Shopping" only writes a line on Kebold's own shopping list.
--
-- EVERYTHING ABOUT THE WRITS IS FROM WOWHEAD'S ITEM TOOLTIPS AND GUIDE SITES OF THE BETA AND HAS NOT BEEN SEEN IN
-- GAME (see Writs.lua): the reputation per rank, the standings' sizes, the quantities, the customers, the receipt.
-- The Coin Pouch's silver is not known: it counts as 0 and is shown with ?. The Legacy talent Diplomat (said to
-- give 10% more reputation) is NOT applied.
--
-- ---- how a writ is costed ---------------------------------------------------------------------------------------------
-- N = how many deliveries are priced (1: each distinct order can be delivered once a day).
--   the item  buy: the engine's supply of the wanted item (ctx.supplyOf) walked over the WHOLE quantity N x the writ's
--             quantity with the shopping list's walk (NS.shopWalk): thin listings raise the price, and a quantity
--             that is not all listed has no buy cost. make: when a recipe in the data makes it, what Kebold says one
--             made unit costs in that profession's own context (ctx.part(item).craft) times the quantity, at list
--             prices, casting not counted; it competes with buying only when this character knows the recipe or a
--             "Plan for" profile is shown, else it is shown as information. S.pick[item] as everywhere: "have" =
--             costs nothing; "buy" / "craft" = that way when possible; none = the cheaper of the two.
--   the writ  its own cheapest listings at the auction house, walked over N. Without a price the writ counts as
--             nothing and the figures are marked +? (noWrit).
--   total cost = the writ + the item          per point = total cost / reputation
--   item only  = the item alone, for a writ already held (per point then = item only / reputation)
-- The Forged Delivery Receipt (one more row, rank "Receipt"): 15 Merchant's Favor + an empty Waylaid Crate for 50
-- reputation. Its Favor is priced at the cheapest per point figure of the Crates view that counts the crate (f.pp
-- of a crate whose own price is known; when no crate has one, the cheapest figure at all, marked +?), the crate
-- at the cheapest listing of any Waylaid Crate. No crate with a per point figure: no figure.
--
-- ---- API ---------------------------------------------------------------------------------------------------------------
-- NS.writList() -> the writs (Writs.lua's list)        NS.writById(id)        NS.writRank(w) -> its rank's entry
-- NS.writFigures(w [, n]) -> { writ, n, rank, rep1, rep (all n), item, qty, units, bags, buy, short, got, listed,
--     scanned, make, makeProf, makeRecipe, known, canMake, pick, top, vend, itemCost (all n), how = "buy" | "make" |
--     "have", writScanned, writListed, writFirst, writCost (all n), writEach, writShort, noWrit, total (writ + item),
--     itemOnly (= itemCost), pp, ppItem, held, doubt }
-- NS.writReceipt() -> { receipt = true, id, rep1, rep, favor, favorPP, favorFrom (crate), favorNoCrate, est,
--     itemCost (the Favor's cost), crateCost, crateFrom (crate), noWrit (no crate price), total, itemOnly, pp, ppItem,
--     held, needs (reaction), blocked (the standing is known and below it) }
-- NS.writStanding() -> { side, id, name, src = "game" | "typed" | "profile" | nil, api, reaction, label, value, lo,
--     hi, have, size, left, nextLabel, done }
-- NS.writPlan(need, figures, receipt) -> { need, writs, receipts, rep, cost, short, noWrit, est }
-- NS.writRows() -> the view's rows (the first is the caption), title      NS.writDetail(id) -> the pane's rows
-- NS.writStatus() / NS.writCounts() / NS.writScanIDs() / NS.writSelect(id) / NS.writSelected() / NS.writFind(text) /
-- NS.writSortBy(column) / NS.writSortKey() / NS.writAddToShop(id) / NS.writFacts(itemID) (the tooltip's lines) /
-- NS.writOptions() / NS.setWritOpt(key, value) / NS.writPane()
--
-- ---- saved (with Kebold's other settings; NOT engine options) --------------------------------------------------------
-- S.favorView = "writs" while this view shows (nil: Crates)
-- S.writs = { rep = reputation typed in, counted from Neutral 0 (used only when the game gives no standing),
--   rank = 1..3 (nil: all), prof = a profession's name (nil: all), held, priced = the two filters,
--   sort = the sorted column's key, desc }

local NS = KeboldsShinyNS
if type(NS) ~= "table" then return end
local W = KeboldsShinyWrits
if type(W) ~= "table" or type(W.list) ~= "table" or type(NS.favorViews) ~= "table" then return end
local UI = KeboldsShinyUI
local E = NS.E
local floor, ceil, max, min, abs = math.floor, math.ceil, math.max, math.min, math.abs
local DIM, RED, GOLD, GREEN = NS.DIM, NS.RED, NS.GOLD, NS.GREEN
local money, itemName, settings, try = NS.money, NS.itemName, NS.settings, NS.try

local ICON = "Interface\\Icons\\INV_Letter_15"
local RECEIPT = W.receipt.id
local SCAN_TIP = "The 150 Craftsman's Writs and their three envelopes, what they ask for and the materials to make it: the prices the Writs view works with."
local SOURCE_NOTE = "From Wowhead's item tooltips and guide sites of the beta; not seen in game."

-- ---- the data, indexed --------------------------------------------------------------------------------------------------

local byId, wants, profList = {}, {}, {}   -- [writ id] = writ; [wanted item id] = { writ, ... }; the professions in order
do
  local seen = {}
  for _, w in ipairs(W.list) do
    byId[w.id] = w
    if w.item then
      wants[w.item] = wants[w.item] or {}
      wants[w.item][#wants[w.item] + 1] = w
    end
    for _, p in ipairs(w.profs) do
      if not seen[p] then
        seen[p] = true
        profList[#profList + 1] = p
      end
    end
  end
  table.sort(profList)
end

function NS.writList() return W.list end
function NS.writById(id) return byId[id] end
function NS.writWants(item) return wants[item] end
function NS.writRank(w) return W.ranks[w.rank] end

local function store()
  local S = settings()
  if type(S.writs) ~= "table" then S.writs = {} end
  return S.writs
end

local function numText(v)
  if abs(v - floor(v + 0.5)) < 1e-9 then return tostring(floor(v + 0.5)) end
  return (string.format("%.2f", v):gsub("0+$", ""))
end

-- 12500 -> "12,500"
local function thousands(v)
  local s = tostring(floor(v + 0.5))
  local out = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
  return (out:gsub("^,", ""))
end

-- The game's own name of an item the shipped data has no name for (a writ, an envelope, the receipt); nil until
-- the client has loaded it. Asked for once.
local asked = {}
local function liveName(id)
  local live = type(C_Item) == "table" and try(C_Item.GetItemNameByID, id) or nil
  if type(live) == "string" and live ~= "" then return live end
  if not asked[id] then
    asked[id] = true
    if type(C_Item) == "table" and type(C_Item.RequestLoadItemDataByID) == "function" then pcall(C_Item.RequestLoadItemDataByID, id) end
  end
  return nil
end

-- What a writ asks for, by the game's name of the item; the English name only when the item id is not known.
local function wantName(w)
  if w.item then return itemName(w.item) end
  return w.name
end
local function wantText(w)
  return (w.qty > 1 and (w.qty .. " ") or "") .. wantName(w)
end
NS.writWantText = wantText

local function receiptName()
  return liveName(RECEIPT) or "Forged Delivery Receipt"
end
local function envelopeName(rank)
  local r = W.ranks[rank]
  return liveName(r.envelope) or ("Sealed " .. r.name .. "'s Writ")
end

-- ---- the standing --------------------------------------------------------------------------------------------------------
-- Read from the game when it says: C_Reputation.GetFactionDataByID(id) (currentStanding, currentReactionThreshold,
-- nextReactionThreshold, reaction), else the old GetFactionInfoByID(id) (3rd value the standing, 4th and 5th the
-- step's two ends, 6th the reputation). WHICH OF THE TWO THE FOREVER CLIENT HAS IS NOT KNOWN: both are probed with
-- type() and called through pcall. When neither answers, a value typed on the Settings page (counted from
-- Neutral 0) is used. A "Plan for" profile is a fresh character: Neutral, 0.

local STEP_AT = {}   -- [reaction] = { lo, hi (nil: the last), name, next }
do
  local at = 0
  for i, s in ipairs(W.steps) do
    STEP_AT[s.reaction] = { lo = at, hi = s.size and (at + s.size) or nil, name = s.name, next = W.steps[i + 1] and W.steps[i + 1].name or nil }
    at = at + (s.size or 0)
  end
  W.cap = at   -- the reputation Exalted starts at
end

local function reactionLabel(reaction)
  local live = type(reaction) == "number" and _G["FACTION_STANDING_LABEL" .. reaction] or nil
  if type(live) == "string" and live ~= "" then return live end
  return STEP_AT[reaction] and STEP_AT[reaction].name or "below Neutral"
end

local function reactionOf(value)
  local found = W.steps[1].reaction
  for _, s in ipairs(W.steps) do
    if value >= STEP_AT[s.reaction].lo then found = s.reaction end
  end
  return found
end

local function readGame(fid)
  if type(C_Reputation) == "table" and type(C_Reputation.GetFactionDataByID) == "function" then
    local ok, d = pcall(C_Reputation.GetFactionDataByID, fid)
    if ok and type(d) == "table" and type(d.currentStanding) == "number" then
      return { name = d.name, reaction = d.reaction, value = d.currentStanding, lo = d.currentReactionThreshold, hi = d.nextReactionThreshold, api = "C_Reputation" }
    end
  end
  if type(GetFactionInfoByID) == "function" then
    local ok, name, _, reaction, lo, hi, value = pcall(GetFactionInfoByID, fid)
    if ok and type(value) == "number" then
      return { name = name, reaction = reaction, value = value, lo = lo, hi = hi, api = "GetFactionInfoByID" }
    end
  end
  return nil
end

function NS.writStanding()
  local side = NS.side()
  local fac = side and W.factions[side] or nil
  local s = { side = side, id = fac and fac.id or nil, name = fac and fac.name or "the trade faction" }
  if not fac then return s end
  local g
  if NS.who() then
    g = { value = 0, src = "profile" }
  else
    g = readGame(fac.id)
    if g then
      g.src = "game"
    else
      local typed = tonumber(store().rep)
      if typed and typed > 0 then g = { value = min(W.cap, floor(typed + 0.5)), src = "typed" } end
    end
  end
  if not g then return s end
  s.src, s.api, s.value = g.src, g.api, g.value
  if type(g.name) == "string" and g.name ~= "" then s.name = g.name end
  s.reaction = type(g.reaction) == "number" and g.reaction or reactionOf(g.value)
  local step = STEP_AT[s.reaction]
  s.lo = type(g.lo) == "number" and g.lo or (step and step.lo or 0)
  s.hi = type(g.hi) == "number" and g.hi or (step and step.hi or nil)
  s.label = reactionLabel(s.reaction)
  s.have = s.value - s.lo
  local last = W.steps[#W.steps].reaction
  if s.reaction >= last or s.hi == nil or s.hi <= s.lo then
    s.done = true
    s.left = 0
  else
    s.done = false
    s.size = s.hi - s.lo
    s.left = max(0, s.hi - s.value)
    s.nextLabel = reactionLabel(s.reaction + 1)
  end
  return s
end

-- The one setting: reputation typed in. { key, label, hint, tip, min, max, step, w, get, set, changed, text }
local OPTIONS
function NS.writOptions()
  if OPTIONS then return OPTIONS end
  OPTIONS = {
    { key = "rep", label = "Writ reputation (typed)", min = 0, max = W.cap, step = 25, w = 50,
      hint = "0 = not typed. Counted from Neutral 0: Friendly 3000, Honored 9000",
      tip = "Your reputation with Durotar Supply and Logistics or the Azeroth Commerce Authority, counted from Neutral 0 (Friendly starts at 3,000, Honored at 9,000, Revered at 21,000, Exalted at 42,000). "
        .. "Only used when the game does not give your standing: the Writs view then works out what the next standing takes from this.",
      get = function() return tonumber(store().rep) or 0 end,
      changed = function() return store().rep ~= nil end,
      text = function()
        local s = NS.writStanding()
        if s.src == "game" then return DIM .. "read from the game: " .. s.label .. " " .. thousands(s.have) .. (s.size and (" / " .. thousands(s.size)) or "") .. "|r" end
        local v = tonumber(store().rep)
        return v and (GOLD .. thousands(v) .. "|r") or (DIM .. "not typed|r")
      end },
  }
  for _, o in ipairs(OPTIONS) do
    o.set = function(v) NS.setWritOpt(o.key, v) end
  end
  return OPTIONS
end

function NS.setWritOpt(key, value)
  local st = store()
  local v = tonumber(value)
  if key == "rep" then
    if v then v = max(0, min(W.cap, floor(v + 0.5))) end
    st.rep = (v and v > 0) and v or nil
  else
    return
  end
  if NS.refresh then NS.refresh() end
end

-- ---- the model: one writ's figures -------------------------------------------------------------------------------------

local function ladderOf(item)
  return E.parseLadder(NS.realmItems()[item])
end

-- The profession context an item is costed in: its maker's, else any (a plain material costs the same in all).
local function stateFor(item)
  local d = NS.data()
  local r = d.maker[item]
  return NS.state(r and r.prof or d.profs[1]), r
end

-- A price for `n` of something that is only bought: cost, each, first, listed, short, scanned.
local function walkOwn(id, n)
  local L = ladderOf(id)
  local out = { scanned = L ~= nil }
  if L then
    out.listed = L.total
    if #L.tiers > 0 then
      out.first = L.tiers[1][1]
      local w = NS.shopWalk(NS.state(NS.data().profs[1]).ctx.supplyOf(id, nil), n)
      if w.short > 1e-9 then
        out.short = w.short
      else
        out.cost, out.each = w.cost, w.cost / n
      end
    end
  end
  return out
end

function NS.writFigures(w, n)
  n = max(1, floor((tonumber(n) or 1) + 0.5))
  local R = W.ranks[w.rank]
  local f = { writ = w, n = n, rank = w.rank, rep1 = R.rep, rep = R.rep * n, item = w.item, qty = w.qty, units = n * w.qty, doubt = w.doubt, bags = 0 }
  local item = w.item
  if item then
    local st, r = stateFor(item)
    local ctx = st.ctx
    local pick = settings().pick[item]
    f.pick, f.bags = pick, NS.bagCount(item)
    local L = ladderOf(item)
    f.scanned, f.listed = L ~= nil, L and L.total or nil
    local part = ctx.part(item)   -- nil for something Kebold treats as a plain material
    if pick == "have" then
      f.itemCost, f.how = 0, "have"
    else
      local stat
      if part then stat = part.buy else stat = ctx.matCost(item).c end
      local walk = NS.shopWalk(ctx.supplyOf(item, stat), f.units)
      if walk.short > 1e-9 then
        f.short, f.got = walk.short, f.units - walk.short
      else
        f.buy, f.top, f.vend = walk.cost, walk.top, walk.vend
      end
    end
    if part then
      f.makeProf = r and r.prof or nil
      f.makeRecipe = r and r.id or nil
      f.known = false
      for _, spell in ipairs(w.spells) do   -- any of the recipes that make it (Gordok Ogre Suit has two)
        local sr = NS.data().byId[spell]
        local ps = sr and NS.state(sr.prof) or nil
        if ps and ps.st.known and ps.st.known[spell] == true then f.known = true end
      end
      if not f.known and r and st.st.known and st.st.known[r.id] == true then f.known = true end
      f.canMake = f.known or NS.who() ~= nil
      if part.craft then f.make = f.units * part.craft end
    end
    if pick ~= "have" then
      local mk = (f.canMake or pick == "craft") and f.make or nil
      if pick == "craft" and mk then
        f.itemCost, f.how = mk, "make"
      elseif pick == "buy" and f.buy then
        f.itemCost, f.how = f.buy, "buy"
      elseif mk and (f.buy == nil or mk < f.buy) then
        f.itemCost, f.how = mk, "make"
      elseif f.buy then
        f.itemCost, f.how = f.buy, "buy"
      end
    end
  end
  -- the writ itself on the auction house
  local own = walkOwn(w.id, n)
  f.writScanned, f.writListed, f.writFirst, f.writCost, f.writEach, f.writShort = own.scanned, own.listed, own.first, own.cost, own.each, own.short
  f.noWrit = f.writCost == nil
  if f.itemCost ~= nil then
    f.itemOnly = f.itemCost
    f.total = f.itemCost + (f.writCost or 0)
    f.pp = f.total / f.rep
    f.ppItem = f.itemOnly / f.rep
  end
  f.held = NS.bagCount(w.id)
  return f
end

-- The Forged Delivery Receipt: 15 Favor at what the cheapest crate makes a point of Favor cost, and the cheapest
-- empty crate. `standing` (optional) says whether the character is Friendly yet.
function NS.writReceipt(standing)
  local R = W.receipt
  local f = { receipt = true, id = R.id, n = 1, rep1 = R.rep, rep = R.rep, favor = R.favor, needs = R.needs, noWrit = true, held = NS.bagCount(R.id), bags = 0 }
  local best, any, crate
  for _, c in ipairs(type(NS.crateList) == "function" and NS.crateList() or {}) do
    local cf = NS.crateFigures(c, 1)
    if cf.pp ~= nil then
      if not cf.noCrate and (best == nil or cf.pp < best.pp) then best = cf end
      if any == nil or cf.pp < any.pp then any = cf end
    end
    if cf.crateEach and (crate == nil or cf.crateEach < crate.crateEach) then crate = cf end
  end
  local src = best or any
  if src then
    f.favorPP, f.favorFrom, f.favorNoCrate, f.est = src.pp, src.crate, src.noCrate == true, src.est == true
    f.itemCost = R.favor * src.pp
    f.itemOnly = f.itemCost
    if crate then f.crateCost, f.crateFrom = crate.crateEach, crate.crate end
    f.noWrit = f.crateCost == nil
    f.total = f.itemCost + (f.crateCost or 0)
    f.pp = f.total / f.rep
    f.ppItem = f.itemOnly / f.rep
  end
  standing = standing or NS.writStanding()
  f.blocked = standing.reaction ~= nil and standing.reaction < R.needs
  return f
end

-- What `need` reputation takes: the cheapest writs first, each once (a distinct order can be delivered once a day),
-- and Forged Delivery Receipts (no limit) from where one is cheaper than the next writ, or when the writs run out.
-- figures: the writs' figures; receipt: its figures or nil (not counted when it has no figure or is blocked).
function NS.writPlan(need, figures, receipt)
  local list = {}
  for _, f in ipairs(figures) do
    if f.pp ~= nil then list[#list + 1] = f end
  end
  table.sort(list, function(a, b)
    if a.pp ~= b.pp then return a.pp < b.pp end
    return a.writ.id < b.writ.id
  end)
  local rc = (receipt and receipt.pp ~= nil and not receipt.blocked) and receipt or nil
  local p = { need = need, writs = 0, receipts = 0, rep = 0, cost = 0, short = 0, noWrit = 0, est = false }
  local left = need
  local function receipts()
    local k = ceil(left / rc.rep - 1e-9)
    p.receipts, p.rep, p.cost = k, p.rep + k * rc.rep, p.cost + k * rc.total
    if rc.noWrit then p.noWrit = p.noWrit + 1 end
    if rc.est then p.est = true end
    left = 0
  end
  for _, f in ipairs(list) do
    if left <= 0 then break end
    if rc and rc.pp <= f.pp then
      receipts()
      break
    end
    p.writs, p.rep, p.cost = p.writs + 1, p.rep + f.rep1, p.cost + f.total / f.n
    if f.noWrit then p.noWrit = p.noWrit + 1 end
    left = left - f.rep1
  end
  if left > 0 and rc then receipts() end
  p.short = max(0, left)
  return p
end

function NS.writScanIDs()
  local ids, seen = {}, {}
  local function add(id)
    if type(id) == "number" and id > 0 and not seen[id] then
      seen[id] = true
      ids[#ids + 1] = id
    end
  end
  for _, w in ipairs(W.list) do add(w.id) end
  for _, r in ipairs(W.ranks) do add(r.envelope) end
  for _, w in ipairs(W.list) do add(w.item) end
  local d = NS.data()
  for _, w in ipairs(W.list) do   -- what makes the wanted items: their materials, parts' materials included
    for _, spell in ipairs(w.spells) do
      local r = d.byId[spell]
      if r then
        local more = { r.made }
        for _, reg in ipairs(r.regs) do more[#more + 1] = reg[1] end
        if type(NS.recipeItems) == "function" then more = NS.recipeItems(r) end
        for _, id in ipairs(more) do
          if id ~= r.pat then add(id) end
        end
      end
    end
  end
  return ids
end

-- ---- the scan ----------------------------------------------------------------------------------------------------------

if type(NS.scanPresetAdd) == "function" and not NS.writPresetAdded then
  NS.writPresetAdded = true
  NS.scanPresetAdd(function()
    return { key = "writs", word = "writs", count = #NS.writScanIDs(), tip = SCAN_TIP }
  end)
end

-- ---- texts -------------------------------------------------------------------------------------------------------------

-- A cost or a per point figure: "1s 20c"; ~ before an estimate; " +?" when the writ (or the crate) has no price.
local function ppText(v, est, noWrit)
  if v == nil then return DIM .. "-|r" end
  local tail = noWrit and (RED .. " +?|r") or ""
  if v < 0 then return GREEN .. "earns " .. money(-v) .. "|r" .. tail end
  return (est and "~" or "") .. money(v) .. tail
end

local PICK_NOTE = { have = " have it", buy = " buy", craft = " make" }

local function buyWhy(f)
  if f.short then
    if not f.scanned then return "no scan" end
    return numText(max(0, f.got)) .. " listed"
  end
  return nil
end

local function profText(w)
  if #w.profs == 0 then return DIM .. "?|r" end
  return table.concat(w.profs, " / ")
end

local function customerText(w)
  local c = w.customer
  if type(c) ~= "table" then return nil end
  return (c.npc and (c.npc .. ", ") or "") .. c.zone, c.x and string.format("%.1f, %.1f", c.x, c.y) or nil
end

local function vendorOf()
  local side = NS.side()
  local out = {}
  for _, k in ipairs({ "H", "A" }) do
    if side == nil or side == k then
      local v = W.receipt.vendors[k]
      out[#out + 1] = { side = k, text = v.npc .. ", " .. v.zone, where = string.format("%.1f, %.1f", v.x, v.y) }
    end
  end
  return out
end

-- ---- the view: the model ---------------------------------------------------------------------------------------------
-- Rows: the first is { caption = true, left = the standing and what the next one takes, standing, plan }. Then
-- { cols = { Writ, Profession, Rank, Rep, Item cost, Writ cost, Per point, Total cost, Item only }, item = the wanted
--   item's id (the tooltip and the icon), writ = the writ's item id (the receipt: its own id, with receipt = true),
--   action (a click selects it), menu = true, shopMenu (Get it by), tip, and the numbers: rank, rep, qty, wantItem,
--   how, itemCost, writEach, pp, ppItem, total, itemOnly, noWrit, held };
-- or one row with `empty` (shown as the empty state).

local HEADS = { "Writ", "Profession", "Rank", "Rep", "Item cost", "Writ cost", "Per point", "Total cost", "Item only" }
local KEYS = { "name", "prof", "rank", "rep", "item", "writ", "pp", "total", "itemOnly" }
local search = ""
local selID = nil
local lastStatus = ""
local lastCounts = { shown = 0, all = #W.list + 1, priced = 0 }
local page

local SORT = {
  name = function(x) return x.name:lower() end,
  prof = function(x) return x.w and (x.w.profs[1] or nil) or nil end,
  rank = function(x) return x.w and x.w.rank or 0 end,
  rep = function(x) return x.f.rep1 end,
  item = function(x) return x.f.itemCost end,
  writ = function(x) return x.f.receipt and x.f.crateCost or x.f.writEach end,
  pp = function(x) return x.f.pp end,
  total = function(x) return x.f.total end,
  itemOnly = function(x) return x.f.itemOnly end,
}

local function sortKey()
  local k = store().sort
  if type(k) ~= "string" or not SORT[k] then return "pp" end
  return k
end
NS.writSortKey = sortKey

function NS.writSortBy(k)   -- a column's key, or its number
  local st = store()
  if type(k) == "number" then k = KEYS[k] end
  if type(k) ~= "string" or not SORT[k] then return end
  if sortKey() == k then
    st.sort, st.desc = k, not (st.desc == true)
  else
    st.sort, st.desc = k, (k == "rep" or k == "rank")   -- Rep and Rank start high to low, everything else low to high
  end
  if not st.desc then st.desc = nil end
  if NS.resetScroll then NS.resetScroll() end
  NS.refresh()
end

function NS.writSelect(id)
  selID = (byId[id] or id == RECEIPT) and id or nil
  if page and type(page.writPane) == "table" and type(page.writPane.list) == "table" then page.writPane.list.offset = 0 end
  NS.refresh()
end
function NS.writSelected() return selID end
function NS.writFind(text) search = tostring(text or "") end
function NS.writStatus() return lastStatus end
function NS.writCounts() return lastCounts end

local function resetFilters()
  local st = store()
  st.rank, st.prof, st.held, st.priced = nil, nil, nil, nil
  search = ""
  if page and type(page.eWritFind) == "table" then pcall(page.eWritFind.SetText, page.eWritFind, "") end
  if NS.resetScroll then NS.resetScroll() end
  NS.refresh()
end

local function anyPriced()
  local items = NS.realmItems()
  for _, w in ipairs(W.list) do
    for _, id in ipairs({ w.id, w.item or false }) do
      if id then
        local L = E.parseLadder(items[id])
        if L and #L.tiers > 0 then return true end
      end
    end
  end
  return false
end

-- The sentence beside the view's buttons: the standing, what is left to the next one, and what that takes.
local function captionRow(s, figures, receipt)
  local row = { caption = true, standing = s, tip = {} }
  local head = s.name .. ": "
  if s.side == nil then
    row.left = DIM .. "Your faction is not known yet: the standing cannot be read.|r"
    return row
  end
  if s.src == nil then
    row.left = head .. RED .. "standing not read|r" .. DIM .. ": open your reputation window, or type your reputation on the Settings page (Waylaid crates).|r"
    return row
  end
  local from = s.src == "typed" and (GOLD .. " (typed)*|r") or (s.src == "profile" and (DIM .. " (a profile starts at 0)|r") or "")
  if s.done then
    row.left = head .. GREEN .. s.label .. "|r" .. from .. DIM .. ": nothing left to earn.|r"
    return row
  end
  local text = head .. s.label .. " " .. thousands(s.have) .. " / " .. thousands(s.size) .. from .. ". " .. GOLD .. thousands(s.left) .. "|r to " .. s.nextLabel .. ": "
  local p = NS.writPlan(s.left, figures, receipt)
  row.plan = p
  if p.writs == 0 and p.receipts == 0 then
    row.left = text .. DIM .. "nothing is priced yet.|r"
    return row
  end
  local parts = {}
  if p.writs > 0 then parts[#parts + 1] = "the " .. (p.writs == 1 and "cheapest writ" or (p.writs .. " cheapest writs (each once)")) end
  if p.receipts > 0 then parts[#parts + 1] = p.receipts .. (p.receipts == 1 and " receipt" or " receipts") end
  text = text .. table.concat(parts, " and ") .. ", " .. ppText(p.cost, p.est, p.noWrit > 0)
  if p.short > 0 then text = text .. RED .. ", and " .. thousands(p.short) .. " more than the priced writs give|r" end
  row.left = text .. "."
  return row
end

local function nameCell(text, f, doubt)
  return text .. (doubt and (DIM .. " ?|r") or "") .. ((f.held or 0) > 0 and (DIM .. " (" .. f.held .. ")|r") or "")
end

local function itemCell(f)
  if f.pick == "have" then return DIM .. "have it|r" .. GOLD .. "*|r" end
  if f.itemCost ~= nil then
    return money(f.itemCost) .. (f.how == "make" and (DIM .. " made|r") or "") .. (f.pick and (GOLD .. (PICK_NOTE[f.pick] or "") .. "*|r") or "")
  end
  if f.item == nil then return RED .. "?|r" end
  return ((f.scanned and (f.got or 0) > 0) and RED or DIM) .. (buyWhy(f) or "no price") .. "|r"
end

local function writCell(f)
  if f.writEach then return money(f.writEach) end
  if f.writShort then return RED .. numText(f.n - f.writShort) .. " listed|r" end
  if f.writScanned then return DIM .. "0 listed|r" end
  return DIM .. "-|r"
end

local function pickMenuOf(f)
  if not f.item or type(NS.cratePickMenu) ~= "function" then return nil end
  return NS.cratePickMenu({ item = f.item, makeProf = f.makeProf, make = f.make })
end

local function receiptRow(f, s)
  local tip = {}
  tip[#tip + 1] = receiptName() .. ": " .. f.favor .. " Merchant's Favor at your camp's vendor, used on an EMPTY Waylaid Crate for " .. f.rep1 .. " reputation. No daily limit."
  tip[#tip + 1] = (f.blocked and RED or "") .. "Needs " .. reactionLabel(f.needs) .. (f.blocked and (": you are " .. tostring(s.label) .. ".|r") or ".")
  if f.pp ~= nil then
    tip[#tip + 1] = "Item cost: " .. f.favor .. " Favor x " .. NS.plain(ppText(f.favorPP, f.est, f.favorNoCrate)) .. " a point (the cheapest crate: " .. NS.crateLabel(f.favorFrom) .. ")."
    tip[#tip + 1] = f.crateCost and ("Writ cost: the cheapest empty Waylaid Crate, " .. NS.plain(money(f.crateCost)) .. " (" .. NS.crateLabel(f.crateFrom) .. ").")
      or (RED .. "+? no Waylaid Crate has a price|r: the figures are the Favor alone.")
    tip[#tip + 1] = "Item only: the Favor alone, with a crate you already hold."
  else
    tip[#tip + 1] = RED .. "No crate has a per point figure yet|r: scan the crate materials (the Crates view)."
  end
  tip[#tip + 1] = DIM .. SOURCE_NOTE .. "|r"
  tip[#tip + 1] = "Click for how it is worked out."
  return { cols = {
      nameCell(receiptName(), f),
      DIM .. "-|r",
      "Receipt",
      tostring(f.rep1),
      f.itemCost ~= nil and ppText(f.itemCost, f.est, f.favorNoCrate) or (DIM .. "no price|r"),
      f.crateCost and money(f.crateCost) or (DIM .. "-|r"),
      ppText(f.pp, f.est, f.noWrit or f.favorNoCrate),
      ppText(f.total, f.est, f.noWrit or f.favorNoCrate),
      ppText(f.itemOnly, f.est, f.favorNoCrate),
    }, item = RECEIPT, writ = RECEIPT, receipt = true, tip = tip,
    action = function() NS.writSelect(RECEIPT) end,
    rep = f.rep1, itemCost = f.itemCost, writEach = f.crateCost, pp = f.pp, ppItem = f.ppItem, total = f.total, itemOnly = f.itemOnly,
    noWrit = f.noWrit, held = f.held, blocked = f.blocked, est = f.est }
end

function NS.writRows()
  local st = store()
  local SCAN = NS.scanLabel and NS.scanLabel("writs") or "Scan writ items"
  local QUICK = (type(KeboldsShinyScan_HasQuick) == "function" and NS.scanLabel) and NS.scanLabel("quick") or nil
  lastCounts = { shown = 0, all = #W.list + 1, priced = 0 }
  for _, w in ipairs(W.list) do liveName(w.id) end   -- asks the game for the writs' own names, once
  liveName(RECEIPT)

  local standing = NS.writStanding()
  local figures = {}
  for i, w in ipairs(W.list) do figures[i] = NS.writFigures(w, 1) end
  local receipt = NS.writReceipt(standing)
  local out = { captionRow(standing, figures, receipt) }

  if not anyPriced() then
    local nIds = #NS.writScanIDs()
    lastStatus = DIM .. "No writ and nothing a writ asks for has a price yet: " .. SCAN .. " at the auction house.|r"
    out[#out + 1] = { left = "No writ prices yet. " .. SCAN .. " at the auction house.",
      empty = { icon = ICON, title = "No writ prices yet",
        text = "What a point of reputation costs comes from the auction house prices of the writs and of what they ask for. " .. SCAN .. " reads all "
          .. nIds .. " items (the writs, their envelopes, what they ask for and the materials to make it, about " .. NS.scanTime(nIds) .. ", at the auction house)."
          .. (QUICK and (" " .. QUICK .. " reads them too.") or ""),
        button = SCAN, onClick = function() NS.scanButton("writs") end,
        button2 = QUICK, onClick2 = QUICK and function() NS.scanButton("quick") end or nil } }
    return out, "Writs"
  end

  local needle = search:lower()
  local list = {}
  local cheapest
  for i, w in ipairs(W.list) do
    local f = figures[i]
    if f.pp ~= nil then
      lastCounts.priced = lastCounts.priced + 1
      if cheapest == nil or f.pp < cheapest.f.pp then cheapest = { w = w, f = f } end
    end
    local keep = true
    if st.rank and w.rank ~= st.rank then keep = false end
    if keep and st.prof then
      keep = false
      for _, p in ipairs(w.profs) do if p == st.prof then keep = true end end
    end
    if keep and st.held and f.held <= 0 then keep = false end
    if keep and st.priced and f.pp == nil then keep = false end
    if keep and needle ~= "" then
      local hay = wantName(w) .. " " .. W.ranks[w.rank].name .. " " .. table.concat(w.profs, " ") .. " " .. (customerText(w) or "")
      keep = hay:lower():find(needle, 1, true) ~= nil
    end
    if keep then list[#list + 1] = { w = w, f = f, order = i, name = wantName(w) } end
  end
  if receipt.pp ~= nil then lastCounts.priced = lastCounts.priced + 1 end
  do   -- the receipt is one more row, unless a rank or a profession is chosen
    local keep = st.rank == nil and st.prof == nil
    if keep and st.held and receipt.held <= 0 then keep = false end
    if keep and st.priced and receipt.pp == nil then keep = false end
    if keep and needle ~= "" then keep = (receiptName() .. " receipt"):lower():find(needle, 1, true) ~= nil end
    if keep then list[#list + 1] = { f = receipt, order = #W.list + 1, name = receiptName() } end
  end
  if #list == 0 then
    local why = {}
    if needle ~= "" then why[#why + 1] = "Find: " .. search end
    if st.rank then why[#why + 1] = W.ranks[st.rank].name end
    if st.prof then why[#why + 1] = st.prof end
    if st.held then why[#why + 1] = "Only writs I hold" end
    if st.priced then why[#why + 1] = "Only priced" end
    lastStatus = DIM .. "0 of " .. lastCounts.all .. " shown.|r"
    out[#out + 1] = { left = "No writ matches (" .. table.concat(why, ", ") .. ").",
      empty = { icon = "Interface\\Icons\\INV_Misc_Spyglass_02", title = "No writ matches",
        text = "No writ fits " .. table.concat(why, ", ") .. "." .. (st.held and " Only writs I hold lists the opened writs in your bags and bank." or ""),
        button = "Show all", onClick = resetFilters } }
    return out, "Writs"
  end

  local key, desc = SORT[sortKey()], st.desc == true
  table.sort(list, function(a, b)
    local va, vb = key(a), key(b)
    if va == nil or vb == nil then
      if va == nil and vb == nil then return a.order < b.order end
      return vb == nil   -- rows without a value go last, whichever way the column is sorted
    end
    if va == vb then return a.order < b.order end
    if desc then return va > vb end
    return va < vb
  end)

  for _, x in ipairs(list) do
    local w, f = x.w, x.f
    if not w then
      out[#out + 1] = receiptRow(f, standing)
    else
      local R = W.ranks[w.rank]
      local tip = {}
      tip[#tip + 1] = "Craftsman's Writ, " .. R.name .. ": deliver " .. wantText(w) .. " for " .. R.rep .. " reputation. Each distinct order once a day."
      if f.itemCost ~= nil then
        tip[#tip + 1] = "The item: " .. NS.plain(money(f.itemCost)) .. (f.how == "make" and (", made with " .. tostring(f.makeProf)) or (f.how == "have" and " (set to Have it)" or ", bought")) .. "."
      elseif f.item then
        tip[#tip + 1] = RED .. (f.scanned and ("Only " .. numText(f.got or 0) .. " of " .. f.units .. " are listed: it cannot be bought.") or "The item has not been scanned yet.") .. "|r"
      end
      if f.make and not (f.canMake or f.pick == "craft") then
        tip[#tip + 1] = DIM .. "Making it with " .. tostring(f.makeProf) .. " would cost " .. NS.plain(money(f.make)) .. " in materials: you do not know the recipe, so it is shown for information only.|r"
      end
      if f.writEach then
        tip[#tip + 1] = "The writ itself: " .. NS.plain(money(f.writEach)) .. " at the auction house, " .. (f.writListed or 0) .. " listed. It is counted in Per point."
      else
        tip[#tip + 1] = RED .. "+? The writ itself has no price|r (" .. (f.writScanned and "none listed" or "not scanned") .. "): Per point and Total cost are the item alone."
      end
      local where = customerText(w)
      tip[#tip + 1] = where and ("Customer: " .. where .. ".") or (DIM .. "Customer not known.|r")
      if w.doubt then tip[#tip + 1] = RED .. "Doubt:|r " .. w.doubt end
      if f.held > 0 then tip[#tip + 1] = GREEN .. "You hold " .. f.held .. " of this writ.|r" end
      tip[#tip + 1] = DIM .. SOURCE_NOTE .. "|r"
      tip[#tip + 1] = "Click for the details. " .. GOLD .. "Right-click|r for the menu."
      out[#out + 1] = { cols = {
          nameCell(wantText(w), f, w.doubt ~= nil),
          profText(w),
          R.name,
          tostring(R.rep),
          itemCell(f),
          writCell(f),
          ppText(f.pp, false, f.noWrit),
          ppText(f.total, false, f.noWrit),
          ppText(f.itemOnly),
        }, item = w.item, writ = w.id, menu = true, shopMenu = pickMenuOf(f), tip = tip,
        action = function() NS.writSelect(w.id) end,
        rank = w.rank, rep = R.rep, qty = w.qty, wantItem = w.item, how = f.how, itemCost = f.itemCost, writEach = f.writEach,
        pp = f.pp, ppItem = f.ppItem, total = f.total, itemOnly = f.itemOnly, noWrit = f.noWrit, held = f.held }
    end
  end
  lastCounts.shown = #list
  local notes = {}
  if receipt.pp ~= nil and (cheapest == nil or receipt.pp < cheapest.f.pp) and not receipt.blocked then
    notes[#notes + 1] = "Cheapest: " .. NS.plain(ppText(receipt.pp, receipt.est)) .. " a point" .. (receipt.noWrit and " +? crate" or "") .. " (" .. receiptName() .. ")."
  elseif cheapest then
    notes[#notes + 1] = "Cheapest: " .. money(cheapest.f.pp) .. " a point" .. (cheapest.f.noWrit and " +? writ" or " with the writ") .. " (" .. wantText(cheapest.w) .. ", " .. W.ranks[cheapest.w.rank].name .. ")."
  end
  local missing = 0
  for _, x in ipairs(list) do if x.w and x.f.pp ~= nil and x.f.noWrit then missing = missing + 1 end end
  if missing > 0 then notes[#notes + 1] = "+? " .. missing .. " without a price for the writ itself." end
  notes[#notes + 1] = "? the Coin Pouch's silver is not known and not counted; all of it is from guide sites, not seen in game."
  lastStatus = string.format("%d of %d shown, %d priced. ", #list, lastCounts.all, lastCounts.priced) .. table.concat(notes, " ")
  return out, "Writs"
end

-- ---- the pane: one writ ------------------------------------------------------------------------------------------------
-- Rows are { left, right } with key = "item" (menu: Get it by) | "bags" | "buy" | "make" | "way" | "itemCost" |
-- "writ" | "total" | "repN" | "pp" | "itemOnly" | "ppItem" | "held" | "rep" | "pouch" | "favor" | "customer" | "where"
-- | "daily" | "envelope" | "doubt" | "note"; for the receipt also "favorPP" | "favorFrom" | "crate" | "needs" |
-- "vendor". Headings have band = true.
local function notesInto(add)
  add({ key = "note", left = DIM .. "A sealed envelope gives a random writ of its rank.|r", note = "envelope" })
  add({ key = "note", left = DIM .. "Forger's Quill (" .. W.quill.favor .. " Favor, " .. reactionLabel(W.quill.needs) .. "): another random writ of the same rank.|r", note = "quill" })
  add({ key = "note", left = DIM .. "Your first crate or writ ever: +" .. thousands(W.firstRep) .. " reputation and " .. W.firstFavor .. " Favor, once.|r", note = "first" })
  add({ key = "doubt", left = RED .. "? |r" .. DIM .. "The Legacy talent Diplomat (+10% reputation, as the sites tell it) is not counted.|r", note = "diplomat" })
  add({ key = "note", left = DIM .. SOURCE_NOTE .. "|r", note = "source" })
  add({ key = "note", left = DIM .. "Kebold only counts: it never opens or delivers a writ.|r", note = "counts" })
end

local function receiptDetail()
  local s = NS.writStanding()
  local f = NS.writReceipt(s)
  local out = {}
  local function add(row)
    out[#out + 1] = row
    return row
  end
  add({ left = GOLD .. "What it takes|r", band = true })
  add({ key = "favor", left = f.favor .. " Merchant's Favor", right = f.itemCost ~= nil and ppText(f.itemCost, f.est, f.favorNoCrate) or (DIM .. "no price|r"),
    tip = { "Bought with Merchant's Favor at your camp's vendor; it binds when picked up.", "Favor is priced at what the cheapest crate of the Crates view makes one point cost, the crate itself counted." } })
  if f.favorPP ~= nil then
    add({ key = "favorPP", left = DIM .. "   one point of Favor|r", right = ppText(f.favorPP, f.est, f.favorNoCrate) })
    add({ key = "favorFrom", left = DIM .. "   from the cheapest crate: " .. NS.crateLabel(f.favorFrom) .. "|r", crate = f.favorFrom.id })
  else
    add({ key = "favorPP", left = RED .. "   No crate has a per point figure yet: scan the crate materials.|r" })
  end
  add({ key = "crate", left = "+ An empty Waylaid Crate", right = f.crateCost and (money(f.crateCost) .. DIM .. "  " .. NS.crateLabel(f.crateFrom) .. "|r") or (RED .. "?|r" .. DIM .. " none has a price|r"),
    tip = { "The cheapest listing of any Waylaid Crate: the receipt is used on an empty one.", "Without a price the crate counts as nothing and the figures are marked +?." } })
  add({ key = "total", left = "= Total cost", right = ppText(f.total, f.est, f.noWrit or f.favorNoCrate) })
  add({ key = "repN", left = "/ Reputation", right = tostring(f.rep1) })
  add({ key = "pp", left = "= Per point", right = ppText(f.pp, f.est, f.noWrit or f.favorNoCrate) })
  add({ left = "" })
  add({ left = GOLD .. "With a crate you already hold|r", band = true })
  add({ key = "itemOnly", left = "Favor only", right = ppText(f.itemOnly, f.est, f.favorNoCrate) })
  add({ key = "ppItem", left = "Per point then", right = ppText(f.ppItem, f.est, f.favorNoCrate) })
  add({ key = "held", left = "Receipts in your bags", right = f.held > 0 and (GREEN .. f.held .. "|r") or (DIM .. "none|r") })
  add({ left = "" })
  add({ left = GOLD .. "Where|r", band = true })
  add({ key = "needs", left = "Needs " .. reactionLabel(f.needs), right = s.reaction == nil and (DIM .. "standing not read|r") or (f.blocked and (RED .. "you are " .. s.label .. "|r") or (GREEN .. "you are " .. s.label .. "|r")) })
  for _, v in ipairs(vendorOf()) do
    add({ key = "vendor", left = v.text, right = DIM .. v.where .. "|r", side = v.side })
  end
  add({ key = "daily", left = "No daily limit." })
  add({ left = "" })
  notesInto(add)
  return out
end

function NS.writDetail(id)
  if id == RECEIPT then return receiptDetail() end
  local w = byId[id]
  if not w then return {} end
  local f = NS.writFigures(w, 1)
  local R = W.ranks[w.rank]
  local out = {}
  local function add(row)
    out[#out + 1] = row
    return row
  end
  add({ left = GOLD .. "The item|r", band = true })
  add({ key = "item", left = wantText(w) .. (w.doubt and (DIM .. " ?|r") or ""), right = profText(w), item = w.item, menu = true, shopMenu = pickMenuOf(f),
    tip = { "What the customer wants. It may be bought: no profession is needed.", GOLD .. "Right-click|r: Get it by (buy, make, have it), search, link." } })
  add({ key = "bags", left = "In your bags", right = f.bags > 0 and tostring(f.bags) or (DIM .. "none|r") })
  do
    local buy
    if f.pick == "have" then
      buy = DIM .. "have it|r"
    elseif f.buy then
      buy = money(f.buy)
    elseif f.item == nil then
      buy = RED .. "?|r"
    else
      buy = ((f.scanned and (f.got or 0) > 0) and RED or DIM) .. (buyWhy(f) or "-") .. "|r"
    end
    add({ key = "buy", left = "Buy", right = buy,
      tip = { f.buy and ("Buying " .. f.units .. " costs " .. money(f.buy) .. (f.top and (", paying up to " .. money(f.top) .. " each") or "") .. ".")
        or (f.scanned and ("Only " .. numText(f.got or 0) .. " of " .. f.units .. " are listed.") or "Not scanned yet.") } })
    local make
    if f.make then
      make = (f.canMake or f.pick == "craft") and money(f.make) or (DIM .. NS.plain(money(f.make)) .. "|r")
    else
      make = DIM .. "-|r"
    end
    add({ key = "make", left = "Make" .. (f.makeProf and (DIM .. " (" .. f.makeProf .. ")|r") or ""), right = make,
      tip = { f.makeProf and (f.make and ("The materials at list prices (the casting is not counted)"
          .. (f.known and ": you know the recipe." or (NS.who() and "." or ": you do NOT know the recipe, so it is shown for information only.")))
          or "Kebold has no cost for making it (a material has no price, or the plan may not use the recipe).")
        or "Kebold counts this item as bought, not made." } })
    local way = f.how == "make" and "make" or (f.how == "have" and "have it" or (f.how == "buy" and "buy" or nil))
    add({ key = "way", left = "Chosen way", right = way and (way .. (f.pick and (GOLD .. "*|r") or "")) or (DIM .. "no price|r"), item = w.item, menu = true, shopMenu = pickMenuOf(f) })
  end

  add({ left = "" })
  add({ left = GOLD .. "One delivery|r", band = true })
  add({ key = "itemCost", left = "Item cost", right = f.itemCost ~= nil and money(f.itemCost) or (DIM .. "no price|r"),
    tip = { "What " .. wantText(w) .. " costs the chosen way.", "What is in your bags is not taken off: set the item to Have it (right-click) when it costs you nothing." } })
  add({ key = "writ", left = "+ Writ cost", right = f.writEach and money(f.writCost) or (RED .. "?|r" .. DIM .. (f.writScanned and " none listed" or " not scanned") .. "|r"),
    tip = { "The cheapest listing of this opened writ" .. (f.writListed and (", " .. f.writListed .. " listed.") or "."),
      "Without a price the writ counts as nothing and Total cost and Per point are marked +?.",
      "Writs also come out of the sealed envelopes, at random." } })
  add({ key = "total", left = "= Total cost", right = ppText(f.total, false, f.noWrit) })
  add({ key = "repN", left = "/ Reputation", right = tostring(f.rep1) })
  add({ key = "pp", left = "= Per point", right = ppText(f.pp, false, f.noWrit),
    tip = { "What one point of reputation costs: Total cost / reputation.", f.noWrit and (RED .. "+? the writ itself has no price, so this is the item alone.|r") or nil } })
  add({ left = "" })
  add({ left = GOLD .. "With a writ you already hold|r", band = true })
  add({ key = "itemOnly", left = "Item only", right = ppText(f.itemOnly) })
  add({ key = "ppItem", left = "Per point then", right = ppText(f.ppItem) })
  add({ key = "held", left = "Writs in your bags", right = f.held > 0 and (GREEN .. f.held .. "|r") or (DIM .. "none|r") })

  add({ left = "" })
  add({ left = GOLD .. "Reward|r", band = true })
  local s = NS.writStanding()
  add({ key = "rep", left = "Reputation", right = tostring(R.rep), tip = { R.name .. " order: " .. R.rep .. " reputation with " .. s.name .. " (five guide sites agree; beta figures).", "No Merchant's Favor." } })
  add({ key = "pouch", left = "Coin Pouch", right = RED .. "?|r" .. DIM .. " counted as 0|r", tip = { "The delivery also gives a Coin Pouch with some silver. How much is not known: it is not counted." } })
  add({ left = "" })
  add({ left = GOLD .. "Deliver to|r", band = true })
  local who, at = customerText(w)
  if who then
    add({ key = "customer", left = who, right = at and (DIM .. at .. "|r") or "", tip = { "From one guide site (wow.gg); not seen in game." } })
  else
    add({ key = "customer", left = DIM .. "customer not known|r", tip = { "The writ's quest says who wants it once you hold the writ." } })
  end
  add({ key = "daily", left = "Each distinct order once a day." })
  do
    local env = walkOwn(R.envelope, 1)
    add({ key = "envelope", left = envelopeName(w.rank), right = env.each and money(env.each) or (DIM .. (env.scanned and "0 listed" or "-") .. "|r"),
      tip = { "The sealed envelope of this rank at the auction house. Opening one gives a random " .. R.name .. " writ, so it is no price for this one." } })
  end
  add({ left = "" })
  if w.doubt then add({ key = "doubt", left = RED .. "? |r" .. DIM .. w.doubt .. "|r", tip = { w.doubt } }) end
  notesInto(add)
  return out
end

-- The wanted item of the selected writ as one plain item on the shopping list. Returns the entry's index, the item
-- and the quantity.
function NS.writAddToShop(id)
  local w = byId[id]
  if not w or not w.item or type(NS.shopAdd) ~= "function" then return nil end
  local at, why = NS.shopAdd({ kind = "item", id = w.item, n = w.qty })
  if at then
    NS.notice("Added " .. wantText(w) .. " to the shopping list (" .. W.ranks[w.rank].name .. " writ).", "info")
  else
    NS.notice("Not added: " .. tostring(why) .. ".")
  end
  return at, w.item, w.qty
end

local function searchWrit(id)
  if not liveName(id) then
    NS.notice("The game has not given this writ's name yet. Search for Craftsman's Writ by hand.")
    return false
  end
  return NS.searchAH(id)
end

-- ---- item tooltips -------------------------------------------------------------------------------------------------
-- On an opened writ: what it wants, its reputation, what a point costs. On something a writ wants: the order and
-- its reputation. As { label, value, text } like NS.itemFacts; as the character itself.
local function writFacts(id)
  local out = {}
  local w = byId[id]
  if w then
    local f = NS.writFigures(w, 1)
    local R = W.ranks[w.rank]
    out[#out + 1] = { label = "Wants", value = wantText(w), text = "Wants: " .. wantText(w) }
    out[#out + 1] = { label = "Reputation", value = R.rep .. DIM .. " (" .. R.name .. " order)|r", text = "Reputation: " .. R.rep .. " (" .. R.name .. " order, from guide sites)" }
    out[#out + 1] = { label = "A point costs", value = ppText(f.pp, false, f.noWrit),
      text = f.pp ~= nil and ("A point costs " .. NS.plain(ppText(f.pp, false, f.noWrit))) or "A point costs: not priced (scan the writ items)" }
  end
  local seen = {}
  for _, ww in ipairs(wants[id] or {}) do
    if not seen[ww.rank] then
      seen[ww.rank] = true
      local R = W.ranks[ww.rank]
      local q = ww.qty > 1 and (", " .. ww.qty .. " needed") or ""
      out[#out + 1] = { label = "Writ", value = R.name .. " order" .. DIM .. " (" .. R.rep .. " reputation" .. q .. ")|r",
        text = "Writ: " .. R.name .. " order (" .. R.rep .. " reputation" .. q .. ")" }
    end
  end
  return out
end
function NS.writFacts(id)
  if type(id) ~= "number" or not (byId[id] or wants[id]) then return {} end
  if type(NS.asMe) == "function" then return NS.asMe(writFacts, id) end
  return writFacts(id)
end

if type(NS.itemFacts) == "function" and not NS.writFactsHooked then
  NS.writFactsHooked = true
  local inner = NS.itemFacts
  NS.itemFacts = function(id, ...)
    local out = inner(id, ...)
    if type(out) == "table" and type(id) == "number" and (byId[id] or wants[id]) then
      local ok, more = pcall(NS.writFacts, id)
      for _, fact in ipairs(ok and type(more) == "table" and more or {}) do out[#out + 1] = fact end
    end
    return out
  end
end

-- ---- the Writs view ----------------------------------------------------------------------------------------------------
-- A view of the Merchant's Favor page (LedgerCrates.lua registers the page; this file adds NS.favorViews.writs).
-- Sizes (all guesses until seen in game):
local WR = {
  rankW = 100, profW = 124, heldW = 118, pricedW = 86, findW = 74, scanW = 104, quickW = 76,   -- the bar's controls
  paneHead = 54, paneFoot = 30, addW = 124, searchW = 94,
}
NS.WR = WR

-- Writ, Per point and Total cost stay with the pane open; the others give way, the highest drop number first. All
-- nine fit the smallest window in every Row size with the pane folded. Widths are for compact rows (the kit scales
-- them).
local COLUMNS = {
  { key = KEYS[1], title = HEADS[1], flex = 1, min = 130, sortable = true,
    tip = { "Writ", "What the opened writ asks for (the quantity when it is more than one).", "(2): you hold two of this writ (bags and bank). ? a doubt about this order (in its details)." } },
  { key = KEYS[2], title = HEADS[2], width = 84, sortable = true, drop = 7,
    tip = { "Profession", "The profession that makes the item. The item may be bought: no profession is needed to deliver it." } },
  { key = KEYS[3], title = HEADS[3], width = 62, sortable = true, drop = 8 },
  { key = KEYS[4], title = HEADS[4], width = 30, align = "RIGHT", sortable = true, drop = 6,
    tip = { "Rep", "The reputation one delivery gives: Journeyman 75, Expert 125, Artisan 200 (guide sites; beta figures). The receipt: 50." } },
  { key = KEYS[5], title = HEADS[5], width = 76, align = "RIGHT", sortable = true, drop = 3,
    tip = { "Item cost", "What the item costs: bought over the whole quantity, or made when you know the recipe and that is cheaper.", "made: cheaper made than bought. A gold * marks your own choice for that item.",
      "The receipt: its 15 Merchant's Favor at what the cheapest crate makes a point of Favor cost." } },
  { key = KEYS[6], title = HEADS[6], width = 54, align = "RIGHT", sortable = true, drop = 4,
    tip = { "Writ cost", "What the opened writ itself costs at the auction house.", "The receipt: the cheapest empty Waylaid Crate." } },
  { key = KEYS[7], title = HEADS[7], width = 60, align = "RIGHT", sortable = true,
    tip = { "Per point", "What one point of reputation costs: Total cost / reputation.", "+? the writ itself has no price yet: the figure is the item alone." } },
  { key = KEYS[8], title = HEADS[8], width = 66, align = "RIGHT", sortable = true,
    tip = { "Total cost", "The writ + the item, for one delivery.", "+? the writ itself has no price yet: the figure is the item alone." } },
  { key = KEYS[9], title = HEADS[9], width = 56, align = "RIGHT", sortable = true, drop = 5,
    tip = { "Item only", "For a writ you already hold: the item alone." } },
}
NS.WRIT_COLUMNS = COLUMNS

local PANE_COLS = {
  { key = "left", flex = 1, min = 150 },
  { key = "right", width = 120, align = "RIGHT" },
}
NS.WRIT_PANE_COLUMNS = PANE_COLS

local function atAH()
  return type(KeboldsShinyScan_AtAuctionHouse) == "function" and KeboldsShinyScan_AtAuctionHouse() and true or false
end

local function buildPane(host)
  local p = CreateFrame("Frame", "KeboldsShinyWritPane", host)
  p:SetPoint("TOPLEFT", host, "TOPLEFT", 0, 0)
  p:SetSize(NS.WIN.detail, 300)
  p.caption = UI.text(p, "dim", "Craftsman's Writ")
  p.caption:SetPoint("TOPLEFT", 4, -2)
  p.icon = p:CreateTexture(nil, "ARTWORK")
  p.icon:SetSize(32, 32)
  p.icon:SetPoint("TOPLEFT", 4, -17)
  p.name = UI.text(p, "section")
  p.name:SetJustifyH("LEFT")
  p.name:SetWordWrap(false)
  p.sub = UI.text(p, "body")
  p.sub:SetJustifyH("LEFT")
  p.sub:SetWordWrap(false)
  p.list = UI.table(p, PANE_COLS, { header = false,
    onClick = function(b, button) NS.rowClick(b, button) end, onEnter = function(b) NS.rowEnter(b) end, onLeave = function(b) NS.rowLeave(b) end,
    empty = { icon = ICON, title = "No writ selected", text = "Click a writ in the list and what it takes shows here: the item bought or made, the writ's own price, the sum, the reward and where to deliver it." } })
  p.list:SetPoint("TOPLEFT", p, "TOPLEFT", 0, -WR.paneHead)
  p.bAdd = UI.button(p, "Add to Shopping", WR.addW, function()
    if selID then NS.writAddToShop(selID) end
  end, { "Add to Shopping", "Puts what the writ asks for on the shopping list.", "It only writes the list: nothing is bought." })
  p.bAdd:SetPoint("BOTTOMLEFT", 2, 3)
  p.bWrit = UI.button(p, "Search writ", WR.searchW, function()
    if selID and byId[selID] then searchWrit(selID) end
  end, { "Search the auction house", "Searches the auction house for this opened writ (the game must know its name)." })
  p.bWrit:SetPoint("LEFT", p.bAdd, "RIGHT", 3, 0)
  p.bItem = UI.button(p, "Search item", WR.searchW, function()
    local w = selID and byId[selID] or nil
    if w and w.item then NS.searchAH(w.item) end
  end, { "Search the auction house", "Searches the auction house for what the writ asks for." })
  p.bItem:SetPoint("LEFT", p.bWrit, "RIGHT", 3, 0)
  p.rows, p.w, p.h, p.shownID = {}, NS.WIN.detail, 300, false
  function p:Layout(w, h)
    self.w, self.h = w, h
    self:SetSize(w, h)
    self.name:SetWidth(w - 46)
    self.sub:SetWidth(w - 46)
    self.list:Layout(w, max(40, h - WR.paneHead - WR.paneFoot))
  end
  function p:Fill(rows, id)
    local w = id and byId[id] or nil
    local isReceipt = id == RECEIPT
    self.rows, self.shownID = rows, (w or isReceipt) and id or false
    local shownItem = w and (w.item or w.id) or (isReceipt and RECEIPT or nil)
    local tex = (shownItem and not UI.plain() and settings().icons ~= false) and (UI.iconOf({ item = shownItem }) or ICON) or nil
    if tex then
      self.icon:SetTexture(tex)
      self.icon:Show()
    else
      self.icon:Hide()
    end
    self.name:ClearAllPoints()
    self.name:SetPoint("TOPLEFT", tex and 42 or 4, -17)
    self.sub:ClearAllPoints()
    self.sub:SetPoint("TOPLEFT", tex and 42 or 4, -35)
    local at = atAH()
    if w then
      local R = W.ranks[w.rank]
      self.name:SetText(wantText(w))
      self.sub:SetText(R.name .. " writ \194\183 " .. R.rep .. " reputation" .. (#w.profs > 0 and (" \194\183 " .. table.concat(w.profs, " / ")) or ""))
      self.bAdd:Show()
      self.bWrit:Show()
      self.bItem:Show()
      self.bAdd:SetEnabled(w.item ~= nil, "The item's id is not known.")
      self.bWrit:SetEnabled(at, "Open the auction house first.")
      self.bItem:SetEnabled(at and w.item ~= nil, at and "The item's id is not known." or "Open the auction house first.")
    else
      self.name:SetText(isReceipt and receiptName() or "")
      self.sub:SetText(isReceipt and ("Receipt \194\183 " .. W.receipt.rep .. " reputation \194\183 " .. W.receipt.favor .. " Merchant's Favor") or "")
      self.bAdd:Hide()
      self.bWrit:Hide()
      self.bItem:Hide()
    end
    self.list:SetRows(rows)
  end
  return p
end

local function buildBar(pg, at, bar)
  local made = {}
  local function put(w, ...)
    made[#made + 1] = w
    return at.put(w, ...)
  end
  local function pickOne(key, value)
    store()[key] = value
    NS.resetScroll()
    NS.refresh()
  end
  pg.dWritRank = put(UI.dropdown(bar, WR.rankW, function()
    local r = store().rank
    return r and W.ranks[r].name or "All ranks"
  end, function()
    local now = store().rank
    local items = { { title = true, text = "Rank" } }
    items[#items + 1] = { radio = true, checked = now == nil, text = "All ranks", func = function() pickOne("rank", nil) end }
    for i, r in ipairs(W.ranks) do
      items[#items + 1] = { radio = true, checked = now == i, text = r.name, tip = r.rep .. " reputation a delivery.", func = function() pickOne("rank", i) end }
    end
    return items
  end, { "Rank", "All 150 writs and the receipt, or the writs of one rank." }))
  pg.dWritProf = put(UI.dropdown(bar, WR.profW, function()
    return store().prof or "All professions"
  end, function()
    local now = store().prof
    local items = { { title = true, text = "Profession" } }
    items[#items + 1] = { radio = true, checked = now == nil, text = "All professions", func = function() pickOne("prof", nil) end }
    for _, p in ipairs(profList) do
      items[#items + 1] = { radio = true, checked = now == p, text = p, func = function() pickOne("prof", p) end }
    end
    return items
  end, { "Profession", "The writs whose item one profession makes. The item may still be bought." }))
  pg.cWritHeld = put(UI.check(bar, "Only writs I hold", function() return store().held and true or false end, function(v)
    pickOne("held", v and true or nil)
  end, { "Only writs I hold", "Only the opened writs (and receipts) in your bags and bank." }), 4, WR.heldW)
  pg.cWritPriced = put(UI.check(bar, "Only priced", function() return store().priced and true or false end, function(v)
    pickOne("priced", v and true or nil)
  end, { "Only priced", "Hides writs without a per point figure: the item has no price." }), 4, WR.pricedW)
  pg.eWritFind = put(UI.search(bar, WR.findW, function(self)
    local t = self:GetText() or ""
    if t ~= search then
      search = t
      NS.resetScroll()
      NS.refresh()
    end
  end), 6)
  pg.eWritFind:SetMaxLetters(30)
  local label = NS.scanLabel and NS.scanLabel("writs") or "Scan writ items"
  pg.bWritScan = put(NS.scanControl(UI.button(bar, label, WR.scanW, function() NS.scanButton("writs") end,
    { label, SCAN_TIP, "It only looks prices up: nothing is bought." })), 4)
  if type(KeboldsShinyScan_HasQuick) == "function" then
    local quick = NS.scanLabel("quick")
    pg.bWritQuick = put(NS.scanControl(UI.button(bar, quick, WR.quickW, function() NS.scanButton("quick") end,
      { quick, "The whole auction house in one request: the writs and what they ask for, among everything else Kebold knows.",
        "The game allows it once per 15 minutes; when the server does not answer it reads gear only.", "It only looks prices up: nothing is bought." }),
      NS.quickWhy), 4)
  end
  return made
end

NS.favorViews.writs = { key = "writs", title = "Writs", columns = COLUMNS,
  tip = { "Writs", "Craftsman's Writs: what each costs to deliver, the reputation it gives, and so which is the cheapest way to the next standing." },
  rows = function() return NS.writRows() end,
  footer = function() return lastStatus end,
  onSort = function(key, k) NS.writSortBy(SORT[key] and key or k) end,
  selected = function(row) return row.writ ~= nil and row.writ == selID end,
  build = function(pg, at, bar)
    page = pg
    return buildBar(pg, at, bar)
  end,
  pane = function(pg, host)
    pg.writPane = buildPane(host)
    return pg.writPane
  end,
  paint = function(pg, paneShown)
    local st = store()
    pg.dWritRank:Refresh()
    pg.dWritProf:Refresh()
    pg.cWritHeld:Refresh()
    pg.cWritPriced:Refresh()
    pg.table:SetSort(sortKey(), st.desc == true)
    if paneShown then
      local id = selID
      pg.writPane:Fill(id and NS.writDetail(id) or {}, id)
    end
  end }

function NS.writPane() return page and page.writPane or nil end   -- for tests
